begin;
update public.lessons set content='{"intro": "Nesta aula vai aprender «Preparar uma angariação juridicamente segura» desde a base. Nenhum termo técnico é assumido como conhecido: primeiro é explicado, depois aplicado. O objetivo é que consiga reconhecer o conceito no trabalho real, explicar o que significa e saber qual é o passo seguinte.", "sections": [{"title": "Termos desta aula", "body": "CMI — CMI significa Contrato de Mediação Imobiliária: contrato escrito que enquadra a relação entre a empresa de mediação e o cliente, identifica o negócio pretendido, o imóvel e as condições essenciais do serviço."}, {"title": "O que é angariação", "body": "Angariação é o processo comercial através do qual a mediadora procura obter a contratação do serviço de mediação por um cliente e reunir condições para comercializar o imóvel com informação adequada."}, {"title": "Antes da reunião", "body": "Identificar pessoa, relação com o imóvel, objetivo, urgência, documentação disponível, expectativas e outros intervenientes."}, {"title": "Na reunião", "body": "Perceber o imóvel e o cliente, explicar serviço, recolher factos, evitar garantir preço ou legalidade sem suporte e definir próximos passos."}, {"title": "Depois da reunião", "body": "Formalizar o enquadramento contratual adequado, organizar documentação e só promover informação que esteja suficientemente confirmada."}, {"title": "Exemplo profissional", "body": "Perante uma situação relacionada com «Preparar uma angariação juridicamente segura», o consultor deve conseguir explicar ao cliente o que sabe, qual a fonte, o que ainda está por confirmar e qual o próximo passo — sem transformar uma hipótese numa certeza."}, {"title": "Limite profissional", "body": "O consultor deve reconhecer a fronteira entre acompanhamento imobiliário e aconselhamento jurídico, fiscal, técnico, financeiro ou urbanístico especializado. Quando a conclusão depende dessa competência, deve encaminhar."}], "takeaway": "No final desta aula deve conseguir explicar «Preparar uma angariação juridicamente segura» sem depender de siglas ou frases decoradas e aplicá-lo num caso simples de trabalho."}'::jsonb, source_url='https://diariodarepublica.pt/dr/detalhe/lei/15-2013-257806', verified_at=date '2026-08-20' where id=158;
update public.lessons set content='{"intro": "Nesta aula vai aprender «Contrato de Mediação Imobiliária — CMI» desde a base. Nenhum termo técnico é assumido como conhecido: primeiro é explicado, depois aplicado. O objetivo é que consiga reconhecer o conceito no trabalho real, explicar o que significa e saber qual é o passo seguinte.", "sections": [{"title": "Termos desta aula", "body": "CMI — CMI significa Contrato de Mediação Imobiliária: contrato escrito que enquadra a relação entre a empresa de mediação e o cliente, identifica o negócio pretendido, o imóvel e as condições essenciais do serviço."}, {"title": "O que é angariação", "body": "Angariação é o processo comercial através do qual a mediadora procura obter a contratação do serviço de mediação por um cliente e reunir condições para comercializar o imóvel com informação adequada."}, {"title": "Antes da reunião", "body": "Identificar pessoa, relação com o imóvel, objetivo, urgência, documentação disponível, expectativas e outros intervenientes."}, {"title": "Na reunião", "body": "Perceber o imóvel e o cliente, explicar serviço, recolher factos, evitar garantir preço ou legalidade sem suporte e definir próximos passos."}, {"title": "Depois da reunião", "body": "Formalizar o enquadramento contratual adequado, organizar documentação e só promover informação que esteja suficientemente confirmada."}, {"title": "Exemplo profissional", "body": "Perante uma situação relacionada com «Contrato de Mediação Imobiliária — CMI», o consultor deve conseguir explicar ao cliente o que sabe, qual a fonte, o que ainda está por confirmar e qual o próximo passo — sem transformar uma hipótese numa certeza."}, {"title": "Limite profissional", "body": "O consultor deve reconhecer a fronteira entre acompanhamento imobiliário e aconselhamento jurídico, fiscal, técnico, financeiro ou urbanístico especializado. Quando a conclusão depende dessa competência, deve encaminhar."}], "takeaway": "No final desta aula deve conseguir explicar «Contrato de Mediação Imobiliária — CMI» sem depender de siglas ou frases decoradas e aplicá-lo num caso simples de trabalho."}'::jsonb, source_url='https://diariodarepublica.pt/dr/detalhe/lei/15-2013-257806', verified_at=date '2026-08-20' where id=159;
update public.lessons set content='{"intro": "Nesta aula vai aprender «Deveres da mediadora durante a angariação» desde a base. Nenhum termo técnico é assumido como conhecido: primeiro é explicado, depois aplicado. O objetivo é que consiga reconhecer o conceito no trabalho real, explicar o que significa e saber qual é o passo seguinte.", "sections": [{"title": "Termos desta aula", "body": "CMI — CMI significa Contrato de Mediação Imobiliária: contrato escrito que enquadra a relação entre a empresa de mediação e o cliente, identifica o negócio pretendido, o imóvel e as condições essenciais do serviço.\n\nRAN — RAN significa Reserva Agrícola Nacional: regime de proteção de solos com aptidão agrícola, sujeito a regras próprias."}, {"title": "O que é angariação", "body": "Angariação é o processo comercial através do qual a mediadora procura obter a contratação do serviço de mediação por um cliente e reunir condições para comercializar o imóvel com informação adequada."}, {"title": "Antes da reunião", "body": "Identificar pessoa, relação com o imóvel, objetivo, urgência, documentação disponível, expectativas e outros intervenientes."}, {"title": "Na reunião", "body": "Perceber o imóvel e o cliente, explicar serviço, recolher factos, evitar garantir preço ou legalidade sem suporte e definir próximos passos."}, {"title": "Depois da reunião", "body": "Formalizar o enquadramento contratual adequado, organizar documentação e só promover informação que esteja suficientemente confirmada."}, {"title": "Exemplo profissional", "body": "Perante uma situação relacionada com «Deveres da mediadora durante a angariação», o consultor deve conseguir explicar ao cliente o que sabe, qual a fonte, o que ainda está por confirmar e qual o próximo passo — sem transformar uma hipótese numa certeza."}, {"title": "Limite profissional", "body": "O consultor deve reconhecer a fronteira entre acompanhamento imobiliário e aconselhamento jurídico, fiscal, técnico, financeiro ou urbanístico especializado. Quando a conclusão depende dessa competência, deve encaminhar."}], "takeaway": "No final desta aula deve conseguir explicar «Deveres da mediadora durante a angariação» sem depender de siglas ou frases decoradas e aplicá-lo num caso simples de trabalho."}'::jsonb, source_url='https://diariodarepublica.pt/dr/detalhe/lei/15-2013-257806', verified_at=date '2026-08-20' where id=160;
update public.lessons set content='{"intro": "Nesta aula vai aprender «Da proposta à preparação do negócio» desde a base. Nenhum termo técnico é assumido como conhecido: primeiro é explicado, depois aplicado. O objetivo é que consiga reconhecer o conceito no trabalho real, explicar o que significa e saber qual é o passo seguinte.", "sections": [{"title": "O conceito central", "body": "«Da proposta à preparação do negócio» deve ser entendido no contexto do módulo «Compra e Venda — Processo Completo». Antes de agir, identifique o objetivo, os intervenientes, a informação de que dispõe e a informação que ainda falta."}, {"title": "Como se aplica", "body": "Transforme o tema numa sequência observável: recolher → confirmar fonte → comparar → identificar risco/divergência → comunicar → encaminhar quando necessário."}, {"title": "O que nunca assumir", "body": "A declaração de um cliente, uma fotografia, um anúncio antigo ou um único documento não substituem a verificação adequada quando a matéria é relevante para o negócio."}, {"title": "Exemplo profissional", "body": "Perante uma situação relacionada com «Da proposta à preparação do negócio», o consultor deve conseguir explicar ao cliente o que sabe, qual a fonte, o que ainda está por confirmar e qual o próximo passo — sem transformar uma hipótese numa certeza."}, {"title": "Limite profissional", "body": "O consultor deve reconhecer a fronteira entre acompanhamento imobiliário e aconselhamento jurídico, fiscal, técnico, financeiro ou urbanístico especializado. Quando a conclusão depende dessa competência, deve encaminhar."}], "takeaway": "No final desta aula deve conseguir explicar «Da proposta à preparação do negócio» sem depender de siglas ou frases decoradas e aplicá-lo num caso simples de trabalho."}'::jsonb, source_url='https://justica.gov.pt/Servicos/Balcao-Casa-Pronta', verified_at=date '2026-08-20' where id=161;
update public.lessons set content='{"intro": "Nesta aula vai aprender «Due diligence antes do CPCV» desde a base. Nenhum termo técnico é assumido como conhecido: primeiro é explicado, depois aplicado. O objetivo é que consiga reconhecer o conceito no trabalho real, explicar o que significa e saber qual é o passo seguinte.", "sections": [{"title": "Termos desta aula", "body": "CPCV — CPCV significa Contrato-Promessa de Compra e Venda: contrato através do qual as partes se comprometem a celebrar posteriormente a compra e venda, nas condições que nele acordarem."}, {"title": "O que é o CPCV", "body": "CPCV significa Contrato-Promessa de Compra e Venda: contrato através do qual as partes se comprometem a celebrar posteriormente a compra e venda, nas condições que nele acordarem."}, {"title": "Partes e imóvel", "body": "O contrato deve identificar corretamente as partes e o imóvel/objeto prometido."}, {"title": "Preço e pagamentos", "body": "Deve tornar claro o preço e o regime dos montantes entregues, incluindo quando assumem natureza de sinal."}, {"title": "Prazos e condições", "body": "Prazo para o ato definitivo, condições, documentação e eventuais dependências como financiamento devem ser redigidos e validados adequadamente."}, {"title": "Papel do consultor", "body": "Organizar factos, transmitir informação e assegurar que questões relevantes são encaminhadas para validação jurídica; não improvisar cláusulas jurídicas."}, {"title": "Exemplo profissional", "body": "Perante uma situação relacionada com «Due diligence antes do CPCV», o consultor deve conseguir explicar ao cliente o que sabe, qual a fonte, o que ainda está por confirmar e qual o próximo passo — sem transformar uma hipótese numa certeza."}, {"title": "Limite profissional", "body": "O consultor deve reconhecer a fronteira entre acompanhamento imobiliário e aconselhamento jurídico, fiscal, técnico, financeiro ou urbanístico especializado. Quando a conclusão depende dessa competência, deve encaminhar."}], "takeaway": "No final desta aula deve conseguir explicar «Due diligence antes do CPCV» sem depender de siglas ou frases decoradas e aplicá-lo num caso simples de trabalho."}'::jsonb, source_url='https://justica.gov.pt/Servicos/Balcao-Casa-Pronta', verified_at=date '2026-08-20' where id=162;
