update public.lessons set content='{"intro": "Nesta aula vai aprender «Sinal e incumprimento» desde a base. Nenhum termo técnico é assumido como conhecido: primeiro é explicado, depois aplicado. O objetivo é que consiga reconhecer o conceito no trabalho real, explicar o que significa e saber qual é o passo seguinte.", "sections": [{"title": "Termos desta aula", "body": "CPCV — CPCV significa Contrato-Promessa de Compra e Venda: contrato através do qual as partes se comprometem a celebrar posteriormente a compra e venda, nas condições que nele acordarem."}, {"title": "O que é o CPCV", "body": "CPCV significa Contrato-Promessa de Compra e Venda: contrato através do qual as partes se comprometem a celebrar posteriormente a compra e venda, nas condições que nele acordarem."}, {"title": "Partes e imóvel", "body": "O contrato deve identificar corretamente as partes e o imóvel/objeto prometido."}, {"title": "Preço e pagamentos", "body": "Deve tornar claro o preço e o regime dos montantes entregues, incluindo quando assumem natureza de sinal."}, {"title": "Prazos e condições", "body": "Prazo para o ato definitivo, condições, documentação e eventuais dependências como financiamento devem ser redigidos e validados adequadamente."}, {"title": "Papel do consultor", "body": "Organizar factos, transmitir informação e assegurar que questões relevantes são encaminhadas para validação jurídica; não improvisar cláusulas jurídicas."}, {"title": "Exemplo profissional", "body": "Perante uma situação relacionada com «Sinal e incumprimento», o consultor deve conseguir explicar ao cliente o que sabe, qual a fonte, o que ainda está por confirmar e qual o próximo passo — sem transformar uma hipótese numa certeza."}, {"title": "Limite profissional", "body": "O consultor deve reconhecer a fronteira entre acompanhamento imobiliário e aconselhamento jurídico, fiscal, técnico, financeiro ou urbanístico especializado. Quando a conclusão depende dessa competência, deve encaminhar."}], "takeaway": "