update public.lessons set content='{"intro": "Nesta aula vai aprender «IMT e Imposto do Selo na aquisição» desde a base. Nenhum termo técnico é assumido como conhecido: primeiro é explicado, depois aplicado. O objetivo é que consiga reconhecer o conceito no trabalho real, explicar o que significa e saber qual é o passo seguinte.", "sections": [{"title": "Termos desta aula", "body": "IMT — IMT significa Imposto Municipal sobre as Transmissões Onerosas de Imóveis, imposto que pode incidir sobre a aquisição onerosa de imóveis nos termos legais."}, {"title": "IMT", "body": "IMT significa Imposto Municipal sobre as Transmissões Onerosas de Imóveis, imposto que pode incidir sobre a aquisição onerosa de imóveis nos termos legais."}, {"title": "Imposto do Selo", "body": "Imposto que pode incidir sobre atos e operações previstos legalmente, incluindo componentes associadas à aquisição/financiamento."}, {"title": "Como trabalhar", "body": "Usar dados atuais do negócio e legislação/tabelas em vigor; tratar resultados como simulação quando não existe liquidação oficial."}, {"title": "Porque não memorizar tabelas", "body": "Taxas, escalões e benefícios podem mudar. O profissional deve saber consultar a fonte atual."}, {"title": "Exemplo profissional", "body": "Perante uma situação relacionada com «IMT e Imposto do Selo na aquisição», o consultor deve conseguir explicar ao cliente o que sabe, qual a fonte, o que ainda está por confirmar e qual o próximo passo — sem transformar uma hipótese numa certeza."}, {"title": "Limite profissional", "body": "O consultor deve reconhecer a fronteira entre acompanhamento imobiliário e aconselhamento jurídico, fiscal, técnico, financeiro ou urbanístico especializado. Quando a conclusão depende dessa competência, deve encaminhar."}], "takeaway": "No final desta aula deve conseguir explicar «IMT e Imposto do Selo na aquisição» sem depender de siglas ou frases decoradas e aplicá-lo num caso simples de trabalho."}'::jsonb, source_url='https://info.portaldasfinancas.gov.pt/pt/informacao_fiscal/codigos_tributarios/cimt/Pages/codigo-do-imt-indice.aspx', verified_at=date '2026-08-20' where id=170;
