update public.lessons set content='{"intro": "Nesta aula vai aprender «IMI, AIMI e fiscalidade na exploração» desde a base. Nenhum termo técnico é assumido como conhecido: primeiro é explicado, depois aplicado. O objetivo é que consiga reconhecer o conceito no trabalho real, explicar o que significa e saber qual é o passo seguinte.", "sections": [{"title": "Termos desta aula", "body": "IMI — IMI significa Imposto Municipal sobre Imóveis, imposto periódico associado à titularidade de imóveis segundo o regime fiscal aplicável.\n\nAIMI — AIMI significa Adicional ao Imposto Municipal sobre Imóveis, aplicável nos termos e condições previstos na legislação fiscal."}, {"title": "O conceito central", "body": "«IMI, AIMI e fiscalidade na exploração» deve ser entendido no contexto do módulo «Fiscalidade Imobiliária». Antes de agir, identifique o objetivo, os intervenientes, a informação de que dispõe e a informação que ainda falta."}, {"title": "Como se aplica", "body": "Transforme o tema numa sequência observável: recolher → confirmar fonte → comparar → identificar risco/divergência → comunicar → encaminhar quando necessário."}, {"title": "O que nunca assumir", "body": "A declaração de um cliente, uma fotografia, um anúncio antigo ou um único documento não substituem a verificação adequada quando a matéria é relevante para o negócio."}, {"title": "Exemplo profissional", "body": "Perante uma situação relacionada com «IMI, AIMI e fiscalidade na exploração», o consultor deve conseguir explicar ao cliente o que sabe, qual a fonte, o que ainda está por confirmar e qual o próximo passo — sem transformar uma hipótese numa certeza."}, {"title": "Limite profissional", "body": "O consultor deve reconhecer a fronteira entre acompanhamento imobiliário e aconselhamento jurídico, fiscal, técnico, financeiro ou urbanístico especializado. Quando a conclusão depende dessa competência, deve encaminhar."}], "takeaway": "No final desta aula deve conseguir explicar «IMI, AIMI e fiscalidade na exploração» sem depender de siglas ou frases decoradas e aplicá-lo num caso simples de trabalho."}'::jsonb, source_url='https://info.portaldasfinancas.gov.pt/pt/informacao_fiscal/codigos_tributarios/cimt/Pages/codigo-do-imt-indice.aspx', verified_at=date '2026-08-20' where id=172;
update public.lessons set content='{"intro": "Nesta aula vai aprender «Contrato e finalidade» desde a base. Nenhum termo técnico é assumido como conhecido: primeiro é explicado, depois aplicado. O objetivo é que consiga reconhecer o conceito no trabalho real, explicar o que significa e saber qual é o passo seguinte.", "sections": [{"title": "Termos desta aula", "body": "REN — REN significa Reserva Ecológica Nacional: regime territorial de proteção de áreas com funções e riscos ecológicos específicos."}, {"title": "RAN", "body": "RAN significa Reserva Agrícola Nacional: regime de proteção de solos com aptidão agrícola, sujeito a regras próprias."}, {"title": "REN", "body": "REN significa Reserva Ecológica Nacional: regime territorial de proteção de áreas com funções e riscos ecológicos específicos."}, {"title": "Como analisar", "body": "Primeiro confirmar incidência cartográfica; depois identificar a operação pretendida; só então consultar o regime aplicável e eventuais procedimentos/compatibilidades."}, {"title": "Erro frequente", "body": "“Está em RAN/REN, logo é impossível” e “há casas ao lado, logo pode construir” são conclusões simplistas."}, {"title": "Exemplo profissional", "body": "Perante uma situação relacionada com «Contrato e finalidade», o consultor deve conseguir explicar ao cliente o que sabe, qual a fonte, o que ainda está por confirmar e qual o próximo passo — sem transformar uma hipótese numa certeza."}, {"title": "Limite profissional", "body": "O consultor deve reconhecer a fronteira entre acompanhamento imobiliário e aconselhamento jurídico, fiscal, técnico, financeiro ou urbanístico especializado. Quando a conclusão depende dessa competência, deve encaminhar."}], "takeaway": "No final desta aula deve conseguir explicar «Contrato e finalidade» sem depender de siglas ou frases decoradas e aplicá-lo num caso simples de trabalho."}'::jsonb, source_url='https://diariodarepublica.pt/dr/legislacao-consolidada/lei/2006-34578375', verified_at=date '2026-08-20' where id=173;
