update public.lessons set content='{"intro": "Nesta aula vai aprender «Dados pessoais na mediação» desde a base. Nenhum termo técnico é assumido como conhecido: primeiro é explicado, depois aplicado. O objetivo é que consiga reconhecer o conceito no trabalho real, explicar o que significa e saber qual é o passo seguinte.", "sections": [{"title": "Termos desta aula", "body": "RGPD — RGPD significa Regulamento Geral sobre a Proteção de Dados, regime europeu que estabelece regras para o tratamento de dados pessoais."}, {"title": "O que são dados pessoais", "body": "Informação relativa a pessoa singular identificada ou identificável."}, {"title": "RGPD", "body": "RGPD significa Regulamento Geral sobre a Proteção de Dados, regime europeu que estabelece regras para o tratamento de dados pessoais."}, {"title": "Base de licitude", "body": "O tratamento precisa de fundamento jurídico adequado. Consentimento é uma das bases possíveis, não a única."}, {"title": "Minimização", "body": "Recolher apenas os dados necessários para a finalidade."}, {"title": "Partilha e segurança", "body": "Documentos de identificação, contactos e dados financeiros não devem circular sem necessidade ou controlo."}, {"title": "Exemplo profissional", "body": "Perante uma situação relacionada com «Dados pessoais na mediação», o consultor deve conseguir explicar ao cliente o que sabe, qual a fonte, o que ainda está por confirmar e qual o próximo passo — sem transformar uma hipótese numa certeza."}, {"title": "Limite profissional", "body": "O consultor deve reconhecer a fronteira entre acompanhamento imobiliário e aconselhamento jurídico, fiscal, técnico, financeiro ou urbanístico especializado. Quando a conclusão depende dessa competência, deve encaminhar."}], "takeaway": "No final desta aula deve conseguir explicar «Dados pessoais na mediação» sem depender de siglas ou frases decoradas e aplicá-lo num caso simples de trabalho."}'::jsonb, source_url='https://diariodarepublica.pt/dr/detalhe/lei/58-2019-123815982', verified_at=date '2026-08-20' where id=182;
