, verified_at=date '2026-08-20' where id=187;
update public.lessons set content='{"intro": "Nesta aula vai aprender «Quando o SCE entra na transação» desde a base. Nenhum termo técnico é assumido como conhecido: primeiro é explicado, depois aplicado. O objetivo é que consiga reconhecer o conceito no trabalho real, explicar o que significa e saber qual é o passo seguinte.", "sections": [{"title": "Termos desta aula", "body": "RAN — RAN significa Reserva Agrícola Nacional: regime de proteção de solos com aptidão agrícola, sujeito a regras próprias.\n\nSCE — SCE significa Sistema de Certificação Energética dos Edifícios."}, {"title": "O que é o certificado energético", "body": "Documento emitido no âmbito do SCE que caracteriza o desempenho energético do edifício ou fração abrangida."}, {"title": "O que deve ler", "body": "Identificação do imóvel, classe energética, validade, técnico emissor e recomendações/informação constante do documento."}, {"title": "Pré-certificado", "body": "Documento aplicável em determinadas fases de projeto/construção, distinto do certificado final."}, {"title": "Publicidade", "body": "Quando o regime exige certificado, a publicidade deve refletir corretamente a classe energética."}, {"title": "Exceções", "body": "Existem exclusões e situações próprias; devem ser confirmadas no regime vigente e no SCE."}, {"title": "Exemplo profissional", "body": "Perante uma situação relacionada com «Quando o SCE entra na transação», o consultor deve conseguir explicar ao cliente o que sabe, qual a fonte, o que ainda está por confirmar e qual o próximo passo — sem transformar uma hipótese numa certeza."}, {"title": "Limite profissional", "body": "O consultor deve reconhecer a fronteira entre acompanhamento imobiliário e aconselhamento jurídico, fiscal, técnico, financeiro ou urbanístico especializado. Quando a conclusão depende dessa competência, deve encaminhar."}], "takeaway": "No final desta aula deve conseguir explicar «Quando o SCE entra na transação» sem depender de siglas ou frases decoradas e aplicá-lo num caso simples de trabalho."}'::jsonb, source_url='https://www.sce.pt/perguntas-frequentes/', verified_at=date '2026-08-20' where id=188;
